import { eq } from 'drizzle-orm'
import { newsletterSubscribers } from '@growth-engine/types/schema'
import { getClientDb } from '../db'

// Basic RFC-ish email check, same spirit as the forms route validation.
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const MAX_EMAIL_LENGTH = 320

/**
 * Newsletter write route. Two actions:
 *
 *   POST /api/rs/newsletter?action=subscribe     body { email, name? }
 *   POST /api/rs/newsletter?action=unsubscribe   body { email }
 *
 * Subscribe is single opt-in with dedupe by lowercased email; re-subscribing
 * flips an `unsubscribed` row back to `subscribed`.
 *
 * Unsubscribe is the self-serve path for someone who no longer has (or never
 * received) an issue with a tokenized link in it. It takes effect immediately.
 *
 * NEITHER response reveals whether the address was on the list — same body for
 * a hit and a miss — so this endpoint can't be used to test whether a given
 * person is a subscriber.
 */
export async function handleNewsletter(
	request: Request,
	tursoUrl: string,
	tursoAuthToken: string,
): Promise<Response> {
	try {
		const url = new URL(request.url)
		const action = url.searchParams.get('action')

		if (request.method !== 'POST') {
			return Response.json({ error: 'Method not allowed' }, { status: 405 })
		}

		if (action !== 'subscribe' && action !== 'unsubscribe') {
			return Response.json({ error: 'Invalid action' }, { status: 400 })
		}

		const body = (await request.json().catch(() => null)) as
			| { email?: unknown; name?: unknown }
			| null

		const email = typeof body?.email === 'string' ? body.email.trim().toLowerCase() : ''
		const rawName = typeof body?.name === 'string' ? body.name.trim() : ''
		const name = rawName.length > 0 ? rawName : null

		if (!email || email.length > MAX_EMAIL_LENGTH || !EMAIL_REGEX.test(email)) {
			return Response.json({ error: 'A valid email is required' }, { status: 400 })
		}

		const db = getClientDb(tursoUrl, tursoAuthToken)
		const now = new Date()

		if (action === 'unsubscribe') {
			const rows = await db
				.select()
				.from(newsletterSubscribers)
				.where(eq(newsletterSubscribers.email, email))
				.limit(1)
			const row = rows[0]

			if (row && row.status !== 'unsubscribed') {
				await db
					.update(newsletterSubscribers)
					.set({ status: 'unsubscribed', unsubscribedAt: now, updatedAt: now })
					.where(eq(newsletterSubscribers.id, row.id))
			}

			// Same body whether or not the address was ever on the list.
			return Response.json({ ok: true, unsubscribed: true })
		}

		const existing = await db
			.select()
			.from(newsletterSubscribers)
			.where(eq(newsletterSubscribers.email, email))
			.limit(1)

		const row = existing[0]

		if (!row) {
			await db.insert(newsletterSubscribers).values({
				id: crypto.randomUUID(),
				email,
				name,
				status: 'subscribed',
				source: 'sdk',
				createdAt: now,
				updatedAt: now,
			})
		} else if (row.status === 'unsubscribed') {
			// Re-subscribe: flip back and clear the unsubscribe attribution.
			await db
				.update(newsletterSubscribers)
				.set({
					status: 'subscribed',
					unsubscribedAt: null,
					unsubscribeIssueId: null,
					...(name ? { name } : {}),
					updatedAt: now,
				})
				.where(eq(newsletterSubscribers.id, row.id))
		} else if (name && name !== row.name) {
			// Already subscribed — idempotent success, just freshen the name.
			await db
				.update(newsletterSubscribers)
				.set({ name, updatedAt: now })
				.where(eq(newsletterSubscribers.id, row.id))
		}

		// Never leak whether the email already existed.
		return Response.json({ ok: true, subscribed: true })
	} catch (err) {
		console.error('[GrowthEngine] newsletter route error:', err)
		return Response.json({ error: 'Internal server error' }, { status: 500 })
	}
}
