import { eq } from 'drizzle-orm'
import {
	forms,
	formSubmissions,
	crmContacts,
	newsletterSubscribers,
} from '@growth-engine/types/schema'
import type { FormField, FormSettings, FormSubmissionMeta } from '@growth-engine/types'
import {
	writeAuditLog,
	NEWSLETTER_OPT_IN_FIELD,
	normalizeSubmissionSourcePath,
} from '@growth-engine/types'
import { getClientDb } from '../db'

/**
 * Best-effort: subscribe the submitter to the newsletter.
 *
 * Two ways a submission can subscribe someone:
 *   - the form IS a newsletter signup form (settings.kind === 'newsletter') —
 *     submitting it IS the opt-in, so every submission subscribes;
 *   - the form is a standard form carrying the opt-in checkbox, and the
 *     submitter actually ticked it.
 *
 * Consent is never assumed: an enabled checkbox that came back false, absent, or
 * as anything other than a real "yes" subscribes nobody.
 *
 * Written with inline drizzle rather than the domain helper on purpose —
 * sdk-server must not import @growth-engine/domain (Node-only, pulls in Mongo
 * and KMS). Mirrors the dedupe rules in routes/newsletter.ts.
 */
async function trySubscribeFromForm(
	db: ReturnType<typeof getClientDb>,
	settings: FormSettings | null,
	fields: FormField[],
	data: Record<string, unknown>,
): Promise<void> {
	try {
		const isNewsletterForm = settings?.kind === 'newsletter'
		const optInEnabled = settings?.newsletterOptIn?.enabled === true
		if (!isNewsletterForm && !optInEnabled) return

		if (!isNewsletterForm) {
			const answer = data[NEWSLETTER_OPT_IN_FIELD]
			const consented = answer === true || answer === 'true' || answer === 'on' || answer === 1
			if (!consented) return
		}

		const emailField = fields.find((f) => f.type === 'email')
		const rawEmail = emailField ? data[emailField.name] : undefined
		const email = typeof rawEmail === 'string' ? rawEmail.trim().toLowerCase() : ''
		if (!email) {
			console.error(
				'[GrowthEngine] newsletter opt-in skipped — the form has no email field with a value',
			)
			return
		}

		// Name is a nice-to-have: first field literally named like a name.
		const nameField = fields.find((f) =>
			['name', 'firstname', 'first_name', 'fullname', 'full_name'].includes(
				f.name.toLowerCase().replace(/\s+/g, ''),
			),
		)
		const rawName = nameField ? data[nameField.name] : undefined
		const name = typeof rawName === 'string' && rawName.trim() ? rawName.trim() : null

		const now = new Date()
		const existing = await db
			.select()
			.from(newsletterSubscribers)
			.where(eq(newsletterSubscribers.email, email))
			.limit(1)
		const row = existing[0]

		if (!row) {
			await db.insert(newsletterSubscribers).values({
				id: crypto.randomUUID(),
				email,
				name,
				status: 'subscribed',
				source: 'sdk',
				createdAt: now,
				updatedAt: now,
			})
			console.log('[GrowthEngine] newsletter opt-in — subscribed via form |', email)
			return
		}

		if (row.status === 'unsubscribed') {
			// They opted out before and are now explicitly asking back in.
			await db
				.update(newsletterSubscribers)
				.set({
					status: 'subscribed',
					unsubscribedAt: null,
					unsubscribeIssueId: null,
					...(name ? { name } : {}),
					updatedAt: now,
				})
				.where(eq(newsletterSubscribers.id, row.id))
			console.log('[GrowthEngine] newsletter opt-in — resubscribed via form |', email)
			return
		}

		if (name && name !== row.name) {
			await db
				.update(newsletterSubscribers)
				.set({ name, updatedAt: now })
				.where(eq(newsletterSubscribers.id, row.id))
		}
	} catch (err) {
		// Best-effort — a newsletter failure must never lose the submission.
		console.error('[GrowthEngine] newsletter opt-in from form failed:', err)
	}
}

/** Best-effort: extract contact fields from form submission and upsert into CRM */
async function tryCreateCrmContact(
	db: ReturnType<typeof getClientDb>,
	submissionId: string,
	data: Record<string, unknown>,
): Promise<void> {
	try {
		const email = (data.email ?? data.Email ?? data.e_mail) as string | undefined
		const firstName = (data.firstName ?? data.first_name ?? data.name ?? data.Name) as string | undefined
		const lastName = (data.lastName ?? data.last_name) as string | undefined
		const phone = (data.phone ?? data.Phone ?? data.telephone) as string | undefined
		const company = (data.company ?? data.Company ?? data.organization) as string | undefined

		if (!email && !firstName) return

		// Deduplicate by email if present
		if (email) {
			const existing = await db
				.select({ id: crmContacts.id })
				.from(crmContacts)
				.where(eq(crmContacts.email, String(email)))
				.limit(1)
			if (existing.length > 0) return
		}

		const parts = firstName ? String(firstName).split(' ') : ['Unknown']
		const first = parts[0] ?? 'Unknown'
		const last = lastName ? String(lastName) : parts.slice(1).join(' ') || 'Unknown'

		await db.insert(crmContacts).values({
			id: crypto.randomUUID(),
			firstName: first,
			lastName: last,
			email: email ? String(email) : null,
			phone: phone ? String(phone) : null,
			company: company ? String(company) : null,
			source: 'form',
			sourceId: submissionId,
			status: 'active',
			createdAt: new Date(),
			updatedAt: new Date(),
		})
	} catch (err) {
		// Best-effort — don't fail the form submission
		console.error('[GrowthEngine] auto-create CRM contact failed:', err)
	}
}

/** Best-effort: notify configured emails about a new form submission */
async function tryNotifyEmails(
	brainApiUrl: string,
	brainApiKey: string,
	formName: string,
	formSlug: string,
	fields: FormField[],
	data: Record<string, unknown>,
	notifyEmails: string[],
	senderEmail?: string,
	customMessage?: string,
	useEmailTemplate?: boolean,
	from?: string,
): Promise<void> {
	const url = `${brainApiUrl}/api/sdk/forms/notify`
	const startedAt = Date.now()
	console.log(
		`[GrowthEngine] forms.notify → POST ${url} | form=${formSlug} | recipients=${notifyEmails.length} [${notifyEmails.join(', ')}] | replyTo=${senderEmail ?? '(none)'} | from=${from ?? '(default)'} | useEmailTemplate=${useEmailTemplate ?? false}`,
	)
	try {
		const res = await fetch(url, {
			method: 'POST',
			headers: {
				'Content-Type': 'application/json',
				'x-api-key': brainApiKey,
			},
			body: JSON.stringify({
				formName,
				formSlug,
				fields: fields.map((f) => ({ label: f.label, name: f.name })),
				data,
				notifyEmails,
				submittedAt: new Date().toISOString(),
				...(senderEmail ? { senderEmail } : {}),
				...(from ? { from } : {}),
				...(customMessage ? { customMessage } : {}),
				...(useEmailTemplate ? { useEmailTemplate } : {}),
			}),
		})

		const durationMs = Date.now() - startedAt
		const contentType = res.headers.get('content-type') ?? '(none)'
		const rawBody = await res.text().catch(() => '(unreadable body)')

		// Non-2xx: request reached the edge but Brain rejected it (auth, 4xx, 5xx).
		if (!res.ok) {
			console.error(
				`[GrowthEngine] forms.notify FAILED | status=${res.status} | contentType=${contentType} | durationMs=${durationMs} | body=${rawBody.slice(0, 300)}`,
			)
			return
		}

		// 2xx but not JSON → almost certainly never hit the Next route
		// (Vercel deployment-protection / SSO / a redirect landing page all return 2xx HTML).
		let parsed: { ok?: boolean; sent?: number; total?: number } | null = null
		try {
			parsed = JSON.parse(rawBody) as { ok?: boolean; sent?: number; total?: number }
		} catch {
			console.error(
				`[GrowthEngine] forms.notify WARN non-JSON 2xx body | status=${res.status} | contentType=${contentType} | the request likely did NOT reach the Brain route (deployment protection / SSO / redirect). body=${rawBody.slice(0, 300)}`,
			)
			return
		}

		const sent = typeof parsed?.sent === 'number' ? parsed.sent : undefined
		const total = typeof parsed?.total === 'number' ? parsed.total : notifyEmails.length
		if (sent === undefined) {
			// Reached the route but the response shape is older/unexpected — still useful to see.
			console.log(
				`[GrowthEngine] forms.notify accepted | status=${res.status} | durationMs=${durationMs} | response=${rawBody.slice(0, 200)}`,
			)
		} else if (sent < total) {
			// Reached Brain, Brain tried to send, but Resend failed for some/all recipients.
			console.error(
				`[GrowthEngine] forms.notify PARTIAL | only ${sent}/${total} emails sent — emails are failing INSIDE Brain. Check Brain logs for '[GrowthEngine] form submission email failed' / 'form submission email error'. durationMs=${durationMs}`,
			)
		} else {
			console.log(`[GrowthEngine] forms.notify OK | ${sent}/${total} emails sent | durationMs=${durationMs}`)
		}
	} catch (err) {
		// fetch itself threw — DNS, TLS, timeout, connection refused.
		console.error(`[GrowthEngine] forms.notify THREW after ${Date.now() - startedAt}ms | url=${url} | error:`, err)
	}
}

/** Best-effort: send confirmation email to form submitter via Brain webhook */
async function trySendConfirmationEmail(
	brainApiUrl: string,
	brainApiKey: string,
	senderEmail: string,
	formName: string,
	subject?: string,
	message?: string,
	data?: Record<string, unknown>,
	replyTo?: string,
	useEmailTemplate?: boolean,
	from?: string,
): Promise<void> {
	const url = `${brainApiUrl}/api/sdk/forms/confirm`
	const startedAt = Date.now()
	console.log(
		`[GrowthEngine] forms.confirm → POST ${url} | to=${senderEmail} | form=${formName} | replyTo=${replyTo ?? '(none)'} | from=${from ?? '(default)'} | useEmailTemplate=${useEmailTemplate ?? false}`,
	)
	try {
		const res = await fetch(url, {
			method: 'POST',
			headers: {
				'Content-Type': 'application/json',
				'x-api-key': brainApiKey,
			},
			body: JSON.stringify({
				to: senderEmail,
				formName,
				subject,
				message,
				...(data ? { data } : {}),
				...(replyTo ? { replyTo } : {}),
				...(from ? { from } : {}),
				...(useEmailTemplate ? { useEmailTemplate } : {}),
			}),
		})

		const durationMs = Date.now() - startedAt
		const contentType = res.headers.get('content-type') ?? '(none)'
		const rawBody = await res.text().catch(() => '(unreadable body)')

		if (!res.ok) {
			console.error(
				`[GrowthEngine] forms.confirm FAILED | status=${res.status} | contentType=${contentType} | durationMs=${durationMs} | body=${rawBody.slice(0, 300)}`,
			)
			return
		}

		// 2xx HTML → never reached the route (deployment protection / SSO / redirect).
		if (!contentType.includes('application/json') && rawBody.trim().startsWith('<')) {
			console.error(
				`[GrowthEngine] forms.confirm WARN non-JSON 2xx body | status=${res.status} | contentType=${contentType} | the request likely did NOT reach the Brain route (deployment protection / SSO / redirect). body=${rawBody.slice(0, 300)}`,
			)
			return
		}

		console.log(
			`[GrowthEngine] forms.confirm OK | status=${res.status} | durationMs=${durationMs} | response=${rawBody.slice(0, 200)}`,
		)
	} catch (err) {
		console.error(`[GrowthEngine] forms.confirm THREW after ${Date.now() - startedAt}ms | url=${url} | error:`, err)
	}
}

/**
 * Capture where the submission came from so conversions can be credited to the
 * page that produced them ("this blog post drove N quote requests").
 *
 * `sourcePath` prefers the explicit path the SDK client sends
 * (window.location.pathname) and falls back to the Referer header — the fetch
 * to the client site's API route is same-origin, so browsers send the full
 * submitting-page URL by default. Returns null when there is nothing worth
 * storing; the metadata column stays NULL exactly as it did before this
 * feature, and readers already treat NULL as "unattributed".
 */
function buildSubmissionMeta(request: Request, rawSourcePath: unknown): FormSubmissionMeta | null {
	const referrer = request.headers.get('referer')
	const userAgent = request.headers.get('user-agent')
	const sourcePath =
		normalizeSubmissionSourcePath(rawSourcePath) ?? normalizeSubmissionSourcePath(referrer)

	const meta: FormSubmissionMeta = {
		...(sourcePath ? { sourcePath } : {}),
		...(referrer ? { referrer } : {}),
		...(userAgent ? { userAgent } : {}),
	}
	return Object.keys(meta).length > 0 ? meta : null
}

/** Best-effort: trigger connected pipelines via Brain API */
async function tryTriggerPipelines(
	brainApiUrl: string,
	brainApiKey: string,
	formId: string,
	submissionData: Record<string, unknown>,
	db: ReturnType<typeof getClientDb>,
): Promise<void> {
	try {
		// Resolve contact ID and name from submission data
		const email = (submissionData.email ?? submissionData.Email ?? submissionData.e_mail) as string | undefined
		if (!email) return // Can't trigger pipeline without identifying the contact

		const rows = await db
			.select({ id: crmContacts.id, firstName: crmContacts.firstName, lastName: crmContacts.lastName })
			.from(crmContacts)
			.where(eq(crmContacts.email, String(email)))
			.limit(1)

		const contact = rows[0]
		if (!contact) return // No CRM contact yet — pipeline trigger requires a contact

		const contactName = [contact.firstName, contact.lastName].filter(Boolean).join(' ') || 'Unknown'
		const company = (submissionData.company ?? submissionData.Company ?? submissionData.organization) as string | undefined

		const url = `${brainApiUrl}/api/sdk/forms/trigger-pipeline`
		const res = await fetch(url, {
			method: 'POST',
			headers: {
				'Content-Type': 'application/json',
				'x-api-key': brainApiKey,
			},
			body: JSON.stringify({
				formId,
				submissionData,
				contactId: contact.id,
				contactName,
				contactEmail: email,
				...(company ? { contactCompany: company } : {}),
			}),
		})

		if (!res.ok) {
			const body = await res.text().catch(() => '(no body)')
			console.error('[GrowthEngine] pipeline trigger returned error | status:', res.status, '| body:', body)
		} else {
			console.log('[GrowthEngine] pipeline trigger success | formId:', formId)
		}
	} catch (err) {
		console.error('[GrowthEngine] pipeline trigger failed:', err)
	}
}

export async function handleForms(
	request: Request,
	tursoUrl: string,
	tursoAuthToken: string,
	brainApiUrl: string,
	brainApiKey: string,
): Promise<Response> {
	try {
		const url = new URL(request.url)
		const action = url.searchParams.get('action')
		const slug = url.searchParams.get('slug')

		const db = getClientDb(tursoUrl, tursoAuthToken)

		if (action === 'list') {
			const rows = await db
				.select()
				.from(forms)
				.where(eq(forms.status, 'active'))

			return Response.json(rows)
		}

		if (action === 'get' && slug) {
			const rows = await db
				.select()
				.from(forms)
				.where(eq(forms.slug, slug))
				.limit(1)

			return Response.json(rows[0] ?? null)
		}

		if (request.method === 'POST' && action === 'submit' && slug) {
			const body = (await request.json()) as {
				data?: Record<string, unknown>
				sourcePath?: unknown
			}
			const data = body.data

			if (!data || typeof data !== 'object') {
				return Response.json({ error: 'Missing or invalid data field' }, { status: 400 })
			}

			// Look up the form definition
			const formRows = await db
				.select()
				.from(forms)
				.where(eq(forms.slug, slug))
				.limit(1)

			const form = formRows[0]
			if (!form) {
				return Response.json({ error: 'Form not found' }, { status: 404 })
			}

			// Validate required fields
			const fields = JSON.parse(form.fields) as FormField[]
			const missingFields: string[] = []

			for (const field of fields) {
				if (field.required) {
					const value = data[field.name]
					if (value === undefined || value === null || value === '') {
						missingFields.push(field.label)
					}
				}
			}

			if (missingFields.length > 0) {
				return Response.json(
					{ error: `Missing required fields: ${missingFields.join(', ')}` },
					{ status: 400 },
				)
			}

			console.log('[GrowthEngine] form submission received | slug:', slug, '| formId:', form.id)

			const id = crypto.randomUUID()
			const meta = buildSubmissionMeta(request, body.sourcePath)

			await db.insert(formSubmissions).values({
				id,
				formId: form.id,
				data: JSON.stringify(data),
				...(meta ? { metadata: JSON.stringify(meta) } : {}),
				createdAt: new Date(),
			})

			console.log('[GrowthEngine] form submission stored | id:', id, '| slug:', slug)

			// Best-effort: auto-create CRM contact from submission
			await tryCreateCrmContact(db, id, data)

			const settings = form.settings ? (JSON.parse(form.settings) as FormSettings) : null

			// Best-effort: subscribe the submitter when this is a newsletter
			// signup form, or when they ticked the opt-in checkbox.
			await trySubscribeFromForm(db, settings, fields, data)

			// Best-effort: send email notifications if configured
			const notifyEmails = settings?.notifyEmails
			if (notifyEmails && notifyEmails.length > 0) {
				console.log('[GrowthEngine] form has notifyEmails | count:', notifyEmails.length, '| emails:', notifyEmails.join(','))
				const replyToField = settings?.replyToFieldName
					? fields.find((f) => f.name === settings.replyToFieldName && f.type === 'email')
					: fields.find((f) => f.type === 'email')
				const senderEmailForReply = replyToField ? String(data[replyToField.name] ?? '') : ''
				await tryNotifyEmails(brainApiUrl, brainApiKey, form.name, slug, fields, data, notifyEmails, senderEmailForReply || undefined, settings?.notificationEmailMessage, settings?.useEmailTemplateNotification ?? settings?.useEmailTemplate, settings?.notificationFromEmail)
			}

			// Best-effort: send confirmation email to the form submitter
			if (settings?.sendConfirmationEmail) {
				const emailField = fields.find((f) => f.type === 'email')
				const senderEmail = emailField ? String(data[emailField.name] ?? '') : ''
				if (senderEmail) {
					await trySendConfirmationEmail(
						brainApiUrl,
						brainApiKey,
						senderEmail,
						form.name,
						settings.confirmationEmailSubject,
						settings.confirmationEmailMessage,
						data,
						settings.replyToEmail,
						settings.useEmailTemplateConfirmation ?? settings.useEmailTemplate,
						settings.confirmationFromEmail,
					)
				}
			}

			if ((!notifyEmails || notifyEmails.length === 0) && !settings?.sendConfirmationEmail) {
				console.log('[GrowthEngine] no email notifications configured | slug:', slug)
			}

			await writeAuditLog(db, {
				actor: { type: 'sdk', id: null, email: null },
				action: 'form.submit',
				resourceType: 'form_submission',
				resourceId: id,
				metadata: { formId: form.id, formSlug: slug },
			})

			// Best-effort: trigger connected pipelines
			await tryTriggerPipelines(brainApiUrl, brainApiKey, form.id, data, db)

			return Response.json({ ok: true, id })
		}

		return Response.json({ error: 'Invalid action' }, { status: 400 })
	} catch (err) {
		console.error('[GrowthEngine] forms route error:', err)
		return Response.json({ error: 'Internal server error' }, { status: 500 })
	}
}
