import { businessConfig } from '@growth-engine/types/schema'
import type { BusinessConfig } from '@growth-engine/types'
import type { ClientDb } from './content'

export async function getBusinessConfig(db: ClientDb): Promise<BusinessConfig | null> {
  const rows = await db.select().from(businessConfig).limit(1)
  const config = rows[0]
  if (!config) return null

  return {
    ...config,
    hours: config.hours ? JSON.parse(config.hours) : null,
    contact: config.contact ? JSON.parse(config.contact) : null,
    address: config.address ? JSON.parse(config.address) : null,
    seo: config.seo ? JSON.parse(config.seo) : null,
  } as BusinessConfig
}
