import { eq, and, desc } from 'drizzle-orm'
import { blogPosts, forms } from '@growth-engine/types/schema'
import type { BlogPost } from '@growth-engine/types'
import {
	buildBlogTopics,
	rankRelatedPosts,
	topicsForPost,
	type BlogTopic,
	type RankRelatedOptions,
} from '@growth-engine/types/blog-linking'
import {
	bookingUrlFromContact,
	resolveBookingCallToAction,
	type BookingCallToAction,
} from '@growth-engine/types/booking-cta'
import type { ClientDb } from './content'
import { getBusinessConfig } from './config'

// ─── Structural internal linking (SSR) ───────────────────────────────────────
// Related articles, topic hubs and the booking call to action for the blog
// template. Every ranking is the deterministic one in
// `@growth-engine/types/blog-linking`, which is ALSO what the seo-improvement
// loop runs when it counts a post's inbound links — so the links this renders
// are exactly the links the loop believes exist. Do not rank here by hand.

const MAX_POSTS = 5000

/** Every published post in one language, newest first. */
async function publishedPosts(db: ClientDb, locale: string): Promise<BlogPost[]> {
	const rows = await db
		.select()
		.from(blogPosts)
		.where(and(eq(blogPosts.status, 'published'), eq(blogPosts.language, locale)))
		.orderBy(desc(blogPosts.createdAt))
		.limit(MAX_POSTS)
	return rows as BlogPost[]
}

export interface GetRelatedPostsOptions extends RankRelatedOptions {
	/** Defaults to the post's own language. */
	locale?: string | undefined
}

/**
 * The related-articles block for `post`: 3–5 published posts in the same
 * language, best keyword match first, newest posts filling the rest.
 */
export async function getRelatedPosts(
	db: ClientDb,
	post: Pick<BlogPost, 'id' | 'slug' | 'title' | 'content' | 'keywords' | 'language' | 'createdAt'>,
	opts: GetRelatedPostsOptions = {},
): Promise<BlogPost[]> {
	const locale = opts.locale ?? post.language ?? 'en'
	const candidates = await publishedPosts(db, locale)
	const rankOpts: RankRelatedOptions = {}
	if (opts.min !== undefined) rankOpts.min = opts.min
	if (opts.max !== undefined) rankOpts.max = opts.max
	return rankRelatedPosts(post, candidates, rankOpts)
}

/** Every topic hub for a language: keywords shared by two or more published posts. */
export async function getBlogTopics(db: ClientDb, locale = 'en'): Promise<BlogTopic[]> {
	const posts = await publishedPosts(db, locale)
	return buildBlogTopics(posts)
}

/** The hubs one post belongs to, for its "Filed under" row. */
export async function getBlogTopicsForPost(
	db: ClientDb,
	post: Pick<BlogPost, 'slug' | 'language'>,
): Promise<BlogTopic[]> {
	const topics = await getBlogTopics(db, post.language ?? 'en')
	return topicsForPost(post, topics)
}

export interface BlogTopicPage {
	topic: BlogTopic
	/** The hub's posts, newest first, as full rows for the card grid. */
	posts: BlogPost[]
}

/** One hub page, or null when no keyword with that slug is shared by enough posts. */
export async function getBlogTopic(
	db: ClientDb,
	slug: string,
	locale = 'en',
): Promise<BlogTopicPage | null> {
	const posts = await publishedPosts(db, locale)
	const topic = buildBlogTopics(posts).find((t) => t.slug === slug.toLowerCase())
	if (!topic) return null
	const wanted = new Set(topic.postSlugs)
	const bySlug = new Map(posts.filter((p) => wanted.has(p.slug)).map((p) => [p.slug, p]))
	return {
		topic,
		posts: topic.postSlugs.map((s) => bySlug.get(s)).filter((p): p is BlogPost => Boolean(p)),
	}
}

/**
 * Where "Book a free 15-minute discovery call" sends the reader. The owner's
 * own booking link (mirrored from the portal's business settings into this
 * tenant's `business_config.contact` JSON) wins outright; otherwise it is built
 * from the same real destinations the landing-page writer sees — active forms,
 * then the business phone, then its email — and chosen by the same rule. Null
 * when the business has published none of them, in which case the template
 * hides the slot.
 */
export async function getBookingCallToAction(db: ClientDb): Promise<BookingCallToAction | null> {
	const candidates: BookingCallToAction[] = []
	try {
		const rows = await db
			.select({ slug: forms.slug, name: forms.name })
			.from(forms)
			.where(eq(forms.status, 'active'))
			.orderBy(desc(forms.updatedAt))
			.limit(10)
		for (const row of rows) {
			if (!row.slug) continue
			candidates.push({ label: row.name || row.slug, href: `/forms/${row.slug}`, kind: 'form' })
		}
	} catch (err) {
		// A tenant DB behind on migrations has no forms table; the phone and
		// email below still make a valid destination.
		console.error('[GrowthEngine] getBookingCallToAction: forms unavailable:', err)
	}
	const business = await getBusinessConfig(db)
	if (business?.phone) {
		candidates.push({
			label: `Call ${business.name ?? 'us'}`,
			href: `tel:${business.phone.replace(/[^\d+]/g, '')}`,
			kind: 'phone',
		})
	}
	if (business?.email) {
		candidates.push({ label: 'Email us', href: `mailto:${business.email}`, kind: 'email' })
	}
	return resolveBookingCallToAction(candidates, bookingUrlFromContact(business?.contact))
}
