import { eq } from 'drizzle-orm'
import { forms } from '@growth-engine/types/schema'
import type { Form, FormField, FormSettings } from '@growth-engine/types'
import type { ClientDb } from './content'

function parseFormRow(row: typeof forms.$inferSelect): Form {
  return {
    id: row.id,
    slug: row.slug,
    name: row.name,
    description: row.description,
    fields: (typeof row.fields === 'string' ? JSON.parse(row.fields) : row.fields) as FormField[],
    settings: row.settings
      ? (typeof row.settings === 'string' ? JSON.parse(row.settings) : row.settings) as FormSettings
      : null,
    status: row.status as 'active' | 'archived',
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  }
}

export async function getActiveForms(db: ClientDb): Promise<Form[]> {
  const rows = await db
    .select()
    .from(forms)
    .where(eq(forms.status, 'active'))

  return rows.map(parseFormRow)
}

export async function getFormBySlug(
  db: ClientDb,
  slug: string,
): Promise<Form | null> {
  const rows = await db
    .select()
    .from(forms)
    .where(eq(forms.slug, slug))
    .limit(1)

  const row = rows[0]
  if (!row) return null

  return parseFormRow(row)
}
