import { eq, desc } from 'drizzle-orm'
import { landingPages } from '@growth-engine/types/schema'
import type { Page } from '@growth-engine/types'
import type { ClientDb } from './content'

// ─── Landing pages (service[-in-city] money pages) ───────────────────────────
// SSR queries for the client site's landing-page routes. PUBLISHED ONLY — the
// draft a workflow wrote is invisible here until the owner approves it in the
// portal, which is the whole point of the approval rail. There is deliberately
// no options flag to include drafts: a public renderer has no legitimate reason
// to read one, and a flag is how "just for preview" turns into a leak.

const MAX_LIMIT = 1000

export interface GetLandingPagesOptions {
	limit?: number | undefined
	offset?: number | undefined
}

function toPage(row: typeof landingPages.$inferSelect): Page {
	return {
		...row,
		keywords: row.keywords ? (JSON.parse(row.keywords) as string[]) : null,
	} as unknown as Page
}

export async function getLandingPages(
	db: ClientDb,
	opts?: GetLandingPagesOptions,
): Promise<Page[]> {
	const limit = Math.min(opts?.limit && opts.limit > 0 ? opts.limit : MAX_LIMIT, MAX_LIMIT)
	const rows = await db
		.select()
		.from(landingPages)
		.where(eq(landingPages.status, 'published'))
		.orderBy(desc(landingPages.createdAt))
		.limit(limit)
		.offset(opts?.offset ?? 0)
	return rows.map(toPage)
}

export async function getLandingPage(db: ClientDb, slug: string): Promise<Page | null> {
	const rows = await db.select().from(landingPages).where(eq(landingPages.slug, slug)).limit(1)
	const row = rows[0]
	if (!row || row.status !== 'published') return null
	return toPage(row)
}
