// Which of a business's real destinations is "the booking call to action".
//
// Shared by the landing-page context builder (domain) and the SDK's blog
// template (sdk-server), so the "Book a free 15-minute discovery call" slot
// under every post points at the SAME place the landing pages send people. The
// rule is deliberately dumb: a destination whose name says booking beats any
// other form, any form beats the phone, the phone beats email. Nothing is
// invented — an empty candidate list yields null and the slot stays hidden,
// because a button that leads nowhere is worse than no button.

export interface BookingCallToAction {
	/** The destination's own name ("Discovery call", "Contact form", "Call Acme"). */
	label: string
	/** Site-relative for hosted forms (`/forms/discovery-call`), or `tel:` / `mailto:`. */
	href: string
	kind: 'form' | 'phone' | 'email' | 'page'
}

/** The button text every template uses unless the site overrides it. */
export const BOOKING_CTA_DEFAULT_LABEL = 'Book a free 15-minute discovery call'

/** Words in a form's name or slug that mean "this is where you book". */
const BOOKING_WORDS =
	/\b(book|booking|reserve|reservation|discovery|consult|consultation|appointment|schedule|call|demo|quote|estimate|contact|get[\s-]?started|enquir|inquir|talk)/i

const KIND_RANK: Record<BookingCallToAction['kind'], number> = {
	form: 0,
	page: 1,
	phone: 2,
	email: 3,
}

/**
 * The booking destination among `candidates`, or null when there is none.
 * Stable: among equals the earlier candidate wins, so callers pass them in
 * their own preference order (newest form first).
 */
export function pickBookingCallToAction(
	candidates: readonly BookingCallToAction[],
): BookingCallToAction | null {
	let best: { cta: BookingCallToAction; rank: number } | null = null
	candidates.forEach((cta, index) => {
		if (!cta.href) return
		const hosted = cta.kind === 'form' || cta.kind === 'page'
		const named = hosted && BOOKING_WORDS.test(`${cta.label} ${cta.href}`)
		// Named hosted destinations first, then by kind, then by position. A
		// phone number labelled "Call us" is not a booking page, so the name
		// bonus is for hosted destinations only.
		const rank = (named ? 0 : 10) + KIND_RANK[cta.kind] + index / 1000
		if (!best || rank < best.rank) best = { cta, rank }
	})
	return best ? (best as { cta: BookingCallToAction }).cta : null
}

/** Key under which the tenant's Turso `business_config.contact` JSON carries the owner's booking link. */
export const BOOKING_URL_CONTACT_KEY = 'bookingUrl'

/** The label a template shows for the owner's own booking page. */
export const BOOKING_URL_LABEL = 'Online booking'

/**
 * The booking destination when the owner has told us their own booking link:
 * that link wins outright over every candidate the ladder can see, because an
 * Acuity or Calendly page is neither a hosted form nor a phone number and the
 * ladder cannot find it. Without one, `pickBookingCallToAction` decides.
 * Shared by the landing-page context builder and the SDK's post template so
 * both send readers to the SAME place.
 */
export function resolveBookingCallToAction(
	candidates: readonly BookingCallToAction[],
	bookingUrl: string | null | undefined,
): BookingCallToAction | null {
	const own = typeof bookingUrl === 'string' ? bookingUrl.trim() : ''
	if (own) return { label: BOOKING_URL_LABEL, href: own, kind: 'page' }
	return pickBookingCallToAction(candidates)
}

/** Reads the booking link out of a parsed `business_config.contact` JSON value. */
export function bookingUrlFromContact(contact: unknown): string | null {
	if (!contact || typeof contact !== 'object') return null
	const v = (contact as Record<string, unknown>)[BOOKING_URL_CONTACT_KEY]
	return typeof v === 'string' && v.trim() ? v.trim() : null
}
