// ─── AI crawler robots.txt policy ────────────────────────────────────────────
// Tenant-wide "let AI assistants read this site" switch, stored on the tenant
// in MongoDB (the business-config source of truth — the per-tenant Turso
// business_config table is orphaned). SDK-built sites render it into robots.txt
// via @growth-engine/sdk-server's getAiCrawlerRules; the Brain serves it at
// /api/sdk/robots-policy (API-key auth).

export type AiCrawlerPolicyMode = 'allow' | 'block'

export interface AiCrawlerPolicy {
	mode: AiCrawlerPolicyMode
	updatedAt: Date
	/** Lowercased email of whoever flipped it, or null for system writes. */
	updatedBy: string | null
}

/** Wire shape of GET /api/sdk/robots-policy (Brain → client site). */
export interface RobotsPolicyResponse {
	/** null = no policy set — the site keeps its default robots.txt untouched. */
	aiCrawlers: AiCrawlerPolicyMode | null
	/** The AI crawler user-agents the policy applies to (server-owned list). */
	bots: string[]
}
