import type { AiCrawlerPolicyMode, RobotsPolicyResponse } from '@growth-engine/types'

// ─── AI-crawler robots.txt policy ───────────────────────────────────────────
// Lets a client site's src/app/robots.ts render the tenant-wide AI-crawler
// policy set in the Growth Engine portal ("Fix it for me" on the AI Search
// tab / the Operator's allow_ai_crawlers tool) without a redeploy.
//
// The policy is fetched STRAIGHT from the Brain (API-key auth) rather than
// through the site's own /api/rs handler: robots.ts also runs during
// `next build`, when the site can't call itself over HTTP. Every failure mode
// (missing env, network error, bad payload) returns NO extra rules, so the
// site's default robots behavior is never at risk.

export interface GetAiCrawlerRulesOptions {
	/** The Brain instance URL — pass process.env.BRAIN_API_URL. */
	brainApiUrl: string | undefined
	/** The tenant API key — pass process.env.BRAIN_API_KEY. */
	brainApiKey: string | undefined
	/** Next.js data-cache revalidate window in seconds (default 300). */
	revalidateSeconds?: number
}

/** One robots.txt rule group, shaped to spread into MetadataRoute.Robots.rules. */
export interface AiCrawlerRule {
	userAgent: string
	allow?: string
	disallow?: string
}

/** Fetch the tenant's AI-crawler policy from the Brain. Null on any failure. */
export async function fetchRobotsPolicy(
	options: GetAiCrawlerRulesOptions,
): Promise<RobotsPolicyResponse | null> {
	const brainApiUrl = options.brainApiUrl?.trim()
	const brainApiKey = options.brainApiKey?.trim()
	if (!brainApiUrl || !brainApiKey) return null

	try {
		const url = `${brainApiUrl.replace(/\/+$/, '')}/api/sdk/robots-policy`
		const init: RequestInit & { next?: { revalidate: number } } = {
			headers: { 'x-api-key': brainApiKey },
			// Next.js data-cache hint — a policy flip reaches the live robots.txt
			// within this window. Ignored by plain fetch outside Next.
			next: { revalidate: options.revalidateSeconds ?? 300 },
		}
		const res = await fetch(url, init)
		if (!res.ok) {
			console.error(`[GrowthEngine] robots-policy fetch returned ${res.status}`)
			return null
		}
		const data = (await res.json()) as Partial<RobotsPolicyResponse> | null
		if (!data || typeof data !== 'object' || !Array.isArray(data.bots)) return null
		const aiCrawlers: AiCrawlerPolicyMode | null =
			data.aiCrawlers === 'allow' || data.aiCrawlers === 'block' ? data.aiCrawlers : null
		return {
			aiCrawlers,
			bots: data.bots.filter((b): b is string => typeof b === 'string' && b.trim() !== ''),
		}
	} catch (err) {
		console.error('[GrowthEngine] robots-policy fetch failed:', err)
		return null
	}
}

/**
 * PURE. Turn a policy into explicit per-bot robots.txt rule groups. A specific
 * `User-agent` group overrides any blanket `User-agent: *` rules, which is what
 * makes the policy authoritative for these bots. No policy (or no valid data)
 * → no extra rules, preserving the site's default robots behavior.
 */
export function buildAiCrawlerRules(policy: RobotsPolicyResponse | null): AiCrawlerRule[] {
	if (!policy || policy.aiCrawlers === null || policy.bots.length === 0) return []
	if (policy.aiCrawlers === 'allow') {
		return policy.bots.map((bot) => ({ userAgent: bot, allow: '/' }))
	}
	return policy.bots.map((bot) => ({ userAgent: bot, disallow: '/' }))
}

/**
 * The one-call form for a client site's robots.ts: fetch the tenant policy and
 * return the rule groups to append after the default `*` rule. Returns `[]`
 * whenever no policy is set or anything fails.
 *
 *   const aiRules = await getAiCrawlerRules({
 *     brainApiUrl: process.env.BRAIN_API_URL,
 *     brainApiKey: process.env.BRAIN_API_KEY,
 *   })
 *   return { rules: [{ userAgent: '*', allow: '/', disallow: ['/api/'] }, ...aiRules], ... }
 */
export async function getAiCrawlerRules(
	options: GetAiCrawlerRulesOptions,
): Promise<AiCrawlerRule[]> {
	return buildAiCrawlerRules(await fetchRobotsPolicy(options))
}
